function mntRepo($f,$observer=null){if(!class_exists(O\AssignmentOrderOriginalMariaDbMaintenanceRepository::class))throw new TestFailure('INTENDED_RED: declared native maintenance repository absent');return new O\AssignmentOrderOriginalMariaDbMaintenanceRepository($f->db,$f->prefix,$observer);}
function mntCommit(array $changes=[]){return new O\AssignmentOrderOriginalMaintenanceCommit(...($changes+['requestId'=>'00000000-0000-4000-8000-000000000801','systemPrincipalId'=>'ops-worker-02','status'=>O\AssignmentOrderOriginalMaintenanceStatus::COMPLETED,'reason'=>null,'retryable'=>false,'scanned'=>2,'deleted'=>1,'retained'=>1,'failed'=>0,'nextCursor'=>null,'attemptedAtUtc'=>'2026-09-02T09:00:00Z']));}
function mntSeed($f,bool $audit=true,bool $bad=false):void{
 $row=['request_id'=>'00000000-0000-4000-8000-000000000801','system_principal_id'=>'test-maintenance-01','status'=>'completed','reason_code'=>null,'retryable'=>0,'scanned'=>$bad?2:1,'deleted'=>1,'retained'=>0,'failed'=>0,'attempted_at_utc'=>'2026-09-02 09:00:00.000000'];
 $insert=function()use($f,$row,$audit){$f->insert('fm2_assignment_order_original_maintenance_requests',$row+['next_cursor'=>null]);if($audit)$f->insert('fm2_assignment_order_original_maintenance_audits',$row);};if($bad)$f->corrupt($insert);else$insert();
}
function mntReal($f){return O\AssignmentOrderOriginalRealMaintenanceVerificationFactory::create($f->db,new O\AssignmentOrderOriginalProductionConfig($f->privateRoot,$f->prefix,$f->safeLog),new O\AssignmentOrderOriginalMaintenanceAuthorization('test-maintenance-01','assignment_order.original.storage.reconcile'),new O\AssignmentOrderOriginalFixedClock('2026-09-02T09:00:00Z'),new O\AssignmentOrderOriginalNoFaults());}
foreach(['valid','missing-audit','bad-counts'] as $kind)A::case('real-replay-'.$kind,function($f)use($kind){mntSeed($f,$kind!=='missing-audit',$kind==='bad-counts');$before=$f->facts();$r=mntReal($f)->reconcileAssignmentOrderOriginalPrivateOrphans(new O\ReconcileAssignmentOrderOriginalPrivateOrphansCommand('00000000-0000-4000-8000-000000000801','test-maintenance-01','2026-09-02T07:30:00Z',10,null));assertSameValue($kind==='valid'?['replayed',null]:['failed','persistence_failure'],[$r->status()->value,$r->reason()?->value],'stored replay requires complete matching backing');assertSameValue($before,$f->facts(),'replay/corruption no writes');});
A::case('native-commit-read-repeat',function($f){$repo=mntRepo($f);assertSameValue('committed',$repo->commitResultAndAudit(mntCommit())->value,'atomic result/audit');assertSameValue([1,1],[count($f->rows('fm2_assignment_order_original_maintenance_requests')),count($f->rows('fm2_assignment_order_original_maintenance_audits'))],'both committed');$before=$f->facts();assertSameValue('conflict',$repo->commitResultAndAudit(mntCommit())->value,'duplicate request not overwritten');$lookup=$repo->findTerminalRequest('00000000-0000-4000-8000-000000000801');assertSameValue('found',$lookup->status()->value,'public read');assertSameValue([2,1,1,0],[$lookup->result()->scanned(),$lookup->result()->deleted(),$lookup->result()->retained(),$lookup->result()->failed()],'stored counts exact');assertSameValue($before,$f->facts(),'collision/read preserve facts');});
foreach([['requestId'=>'bad'],['systemPrincipalId'=>'bad principal'],['scanned'=>3],['status'=>O\AssignmentOrderOriginalMaintenanceStatus::FAILED],['retryable'=>true],['nextCursor'=>'='],['attemptedAtUtc'=>'bad']] as $n=>$changes)integrityCase('invalid-native-DTO-'.$n,function()use($changes){if(!class_exists(O\AssignmentOrderOriginalMariaDbMaintenanceRepository::class))throw new TestFailure('INTENDED_RED: native repository absent');$db=new S\OriginalIntegrityNoSql();$repo=new O\AssignmentOrderOriginalMariaDbMaintenanceRepository($db,'p_');assertSameValue('rolled_back',$repo->commitResultAndAudit(mntCommit($changes))->value,'invalid commit tuple rejected');assertSameValue([],$db->calls,'invalid DTO before SQL');});
foreach(['bad-prefix',str_repeat('p',26)] as $prefix)integrityCase('invalid-native-prefix-'.strlen($prefix),function()use($prefix){if(!class_exists(O\AssignmentOrderOriginalMariaDbMaintenanceRepository::class))throw new TestFailure('INTENDED_RED: native repository absent');$db=new S\OriginalIntegrityNoSql();$repo=new O\AssignmentOrderOriginalMariaDbMaintenanceRepository($db,$prefix);assertSameValue('rolled_back',$repo->commitResultAndAudit(mntCommit())->value,'invalid prefix refused');assertSameValue([],$db->calls,'invalid prefix before SQL');});
A::case('active-caller-transaction',function($f){$repo=mntRepo($f);$f->db->begin_transaction();$f->db->query("UPDATE `{$f->prefix}fm2_process_tasks` SET due_date='2026-09-03' WHERE id=9001");$before=$f->facts();assertSameValue('rolled_back',$repo->commitResultAndAudit(mntCommit())->value,'writer refuses caller transaction');assertSameValue('unavailable',$repo->findTerminalRequest('00000000-0000-4000-8000-000000000801')->status()->value,'reader refuses caller transaction');assertSameValue(1,(int)$f->db->query('SELECT @@in_transaction active')->fetch_assoc()['active'],'caller transaction remains active');assertSameValue($before,$f->facts(),'caller alone owns pending facts');$f->db->rollback();});
foreach(['before_native_commit','after_native_commit','before_read_release'] as $fault)A::case('native-observer-'.$fault,function($f)use($fault){$observer=new class($fault) implements O\AssignmentOrderOriginalPersistenceObserver{public function __construct(private string $fault){}public function observe(O\AssignmentOrderOriginalPersistenceEvent $event):void{if($event->value===$this->fault)throw new RuntimeException('fixture fault');}};$repo=mntRepo($f,$observer);$status=$repo->commitResultAndAudit(mntCommit());assertSameValue(match($fault){'before_native_commit'=>'rolled_back','after_native_commit'=>'outcome_unknown',default=>'committed'},$status->value,'native acknowledgement classification');assertSameValue($fault==='before_native_commit'?0:1,count($f->rows('fm2_assignment_order_original_maintenance_requests')),'actual durability');if($fault==='before_read_release')assertSameValue('unavailable',$repo->findTerminalRequest('00000000-0000-4000-8000-000000000801')->status()->value,'read release failure not false found');});
integrityDone('ASSIGNMENT_ORDER_ORIGINAL_MAINTENANCE_REPOSITORY_OK');
